#!/usr/bin/env bash
# Print the three most frequent client IP addresses in access.log.
# For equal counts, retain the order in which an address first appears.
set -euo pipefail

awk '
{
    ip = $1
    if (!(ip in count))
        first[ip] = ++seen
    count[ip]++
}
END {
    n = 0
    for (ip in count)
        addresses[++n] = ip

    # Sort explicitly because awk associative-array traversal has no order.
    for (i = 1; i <= n; i++)
        for (j = i + 1; j <= n; j++)
            if (count[addresses[j]] > count[addresses[i]] || \
                (count[addresses[j]] == count[addresses[i]] && \
                 first[addresses[j]] < first[addresses[i]])) {
                tmp = addresses[i]
                addresses[i] = addresses[j]
                addresses[j] = tmp
            }

    limit = n < 3 ? n : 3
    for (i = 1; i <= limit; i++)
        print addresses[i]
}
' access.log
